window.__finlexDocLoaded(10002,{"id":10002,"articles":[{"id":1000003,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Requires firms to design, implement, and operate a risk-based system of quality management (SOQM) covering governance, ethics, acceptance/continuance, engagement performance, resources, information/communication, and monitoring/remediation.","seq":0},{"id":1000004,"no":"ISQM 1.19–56","heading":"Eight Components of Firm Quality Management (SOQM)","text":"Requires firms to design and operate a proactive, risk-based System of Quality Management (SOQM) covering 8 integrated components:\n• (1) Firm's risk assessment process (quality objectives → quality risks → responses); (2) Governance and leadership; (3) Relevant ethical requirements; (4) Acceptance and continuance of client relationships; (5) Engagement performance; (6) Resources (human, technological, intellectual); (7) Information and communication; (8) Monitoring and remediation process.\n• Annual evaluation (ISQM 1.53–55): leadership must evaluate at least annually whether the SOQM provides reasonable assurance that its objectives are being achieved (converged with China QMS 5101).","seq":1},{"id":1000005,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.","seq":2}]});
